insert into public.products (id, slug, name, category, price_cents, description, image_file) values
  ('nf-001', 'ridge-2-dome-tent', 'Ridge 2 Dome Tent', 'tents', 28900, 'A two-person dome tent that pitches in five minutes and sheds wind on exposed ridges.', 'ridge-2-dome-tent.jpg'),
  ('nf-002', 'hollow-pine-3-tent', 'Hollow Pine 3 Tent', 'tents', 34900, 'Roomy three-person tent with two doors, so nobody climbs over anyone at 3 a.m.', 'hollow-pine-3-tent.jpg'),
